'use strict';
const customAssets={welcome:{kind:'form',name:'Club welcome form',paid:false},coursePayment:{kind:'form',name:'Club Course payment form',paid:true},introQuiz:{kind:'quiz',name:'Club orientation quiz',paid:false},topicsSurvey:{kind:'survey',name:'Next Club meeting survey',paid:false}};
function defaultCustomAccess(){return {method:'embed',kind:'form',asset:'welcome',layout:'inline',days:'',button:'View course offer',url:'',confirmation:'context'};}
function customSettings(){const c=draft.custom;return `<p class="hint">Use an existing asset or a simple link. Configure access here, without editing the form or creating a channel-specific workflow.</p><div class="field"><label for="customMethod">What should the locked channel show?</label><select id="customMethod" data-custom="method"><option value="embed" ${c.method==='embed'?'selected':''}>Embedded form, quiz or survey</option><option value="external" ${c.method==='external'?'selected':''}>Description + button to an external funnel</option></select></div>${c.method==='embed'?`<div class="field"><label for="customKind">Asset type</label><select id="customKind" data-custom="kind">${['form','quiz','survey'].map(k=>`<option ${c.kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label for="customAsset">Select existing ${esc(c.kind)}</label><select id="customAsset" data-custom="asset">${Object.entries(customAssets).filter(([,a])=>a.kind===c.kind).map(([id,a])=>`<option value="${id}" ${c.asset===id?'selected':''}>${a.name}</option>`).join('')}</select></div><div class="field"><label for="customLayout">Display</label><select id="customLayout" data-custom="layout"><option value="inline" ${c.layout==='inline'?'selected':''}>On the locked channel page</option><option value="popup" ${c.layout==='popup'?'selected':''}>In a popup opened from the channel</option></select></div><p class="hint">${customAssets[c.asset].paid?'This existing form collects a payment. Unlock after its payment is confirmed, not after an unpaid submission.':'Unlock immediately after a verified final completion from this channel. No extra workflow setup.'} Reusing this asset elsewhere does not unlock this channel.</p>`:`<div class="field"><label for="customButton">Button text</label><input id="customButton" data-custom="button" value="${esc(c.button)}"></div><div class="field"><label for="customUrl">Existing funnel / sales-page URL</label><input id="customUrl" type="url" data-custom="url" value="${esc(c.url)}" placeholder="Paste your existing funnel URL"></div><div class="field"><label for="customConfirmation">How is access confirmed?</label><select id="customConfirmation" data-custom="confirmation"><option value="context" ${c.confirmation==='context'?'selected':''}>Native funnel checkout · automatic channel context</option>${Object.entries(catalog).map(([id,p])=>`<option value="${id}" ${c.confirmation===id?'selected':''}>Existing purchase · ${p.name}</option>`).join('')}<option value="none" ${c.confirmation==='none'?'selected':''}>Link only · access managed separately</option></select></div><p class="hint">The channel shows only your description and button. Payment stays in the external funnel. Native funnel checkout carries the channel context automatically. Existing product matching or separate access automation remains available for other routes. Opening a link never grants access by itself.</p>`}<div class="field"><label for="customDescription">Locked-page description</label><textarea id="customDescription" data-custom-description>${esc(draft.description)}</textarea></div><div class="field"><label for="customDays">Channel access days · leave blank for lifetime</label><input id="customDays" data-custom="days" type="number" min="1" step="1" value="${esc(c.days)}"></div>`;}
function validateCustomAccess(){const c=draft.custom;if(c.days!==''&&(!Number.isSafeInteger(Number(c.days))||Number(c.days)<1))return 'Enter positive whole days, or leave blank for lifetime access.';if(c.method==='external'){let u;try{u=new URL(c.url);}catch{}if(!u||!['https:','http:'].includes(u.protocol))return 'Enter the full HTTP or HTTPS URL of your existing funnel.';if(!c.button.trim())return 'Enter the button text.';}return '';}
function embeddedAssetMarkup(){const c=config.custom,a=customAssets[c.asset];return `<form id="embeddedAccessForm" class="embedded-asset" onsubmit="return false"><h2 class="post-title">${esc(a.name)}</h2><p class="hint">Existing ${esc(a.kind)} · sample preview · signed in as Club member</p>${a.kind==='quiz'?'<div class="field"><label for="accessAnswer">Where can you find the next Club meeting?</label><select id="accessAnswer" required><option value="">Choose an answer</option><option>Events</option><option>Member directory</option></select></div>':a.kind==='survey'?'<div class="field"><label for="accessAnswer">What would you like to discuss at the next Club meeting?</label><textarea id="accessAnswer" required></textarea></div>':'<div class="field"><label for="accessAnswer">What would you like to work on in The Club?</label><input id="accessAnswer" required></div>'}${a.paid?`<div class="offer-row"><div class="offer-info"><strong>Club Course · Full access</strong><small>€149 · one-time · existing form checkout</small></div></div><div class="field"><label>Payment</label><input disabled value="Sample payment fields · no charge"></div>`:''}<p class="hint">${c.days?esc(c.days)+' days of channel access':'Lifetime channel access'} included. Your signed-in identity and this channel are attached automatically.</p><p id="embeddedError" class="error" role="alert" hidden>Payment was not completed. The channel stays locked.</p><div class="footer">${a.paid?'<button type="button" class="secondary" data-action="embeddedPaymentFailure">Simulate payment failure</button>':''}<button type="button" class="primary" data-action="completeEmbedded">${a.paid?'Simulate paid submission & unlock':'Complete & unlock channel'}</button></div></form>`;}
function renderCustomAccess(method){const c=config.custom;channelContent.innerHTML=`<section class="guest"><h1 class="guest-title">${icon('lock')}${esc(config.name)}</h1><p class="description">${esc(config.description)}</p><div class="guest-meta">Private channel · Visible · content locked</div>${method==='external'?`<button class="primary" data-action="externalFunnel">${esc(c.button)}</button>`:c.layout==='popup'?`<button class="primary" data-action="openEmbedded">Open ${esc(c.kind)} to get access</button>`:embeddedAssetMarkup()}</section>`;}
function customGrantBanner(){if(receipt?.source==='Original external funnel')return '<div class="status-banner"><strong>Your funnel purchase unlocked this channel.</strong>You returned to the same feed. The order keeps its original funnel attribution.</div>';return '<div class="status-banner"><strong>Access unlocked immediately.</strong>The selected asset completed in this channel. No separate channel-specific workflow or second sign-up was needed.</div>';}
function showSubmissionActivity(){const r=receipt;modal('Contact activity · channel access',`<p class="description">${esc(r.offer)} completed in ${esc(r.channel)}.</p><table class="summary-table"><tr><th>Completion</th><td>${esc(r.id)}</td></tr><tr><th>Source</th><td>${esc(r.source)}</td></tr><tr><th>Access granted</th><td>${esc(r.duration)}</td></tr><tr><th>Order</th><td>No order or payment was needed for this free completion.</td></tr></table><div class="footer"><button class="primary" data-action="returnFeed">Back to channel</button></div>`);}
function customCompletion(source,paid=false,externalProduct=null){const c=config.custom,a=customAssets[c.asset],p=externalProduct?catalog[externalProduct]:paid?catalog.course:null;grant.custom=true;receipt={kind:paid?'order':'submission',offer:p?p.name:a.name,total:p?p.price:paid?'€149':'No payment',source,channel:config.name,duration:c.days?c.days+' days':'Lifetime',id:paid?'DEMO-CUSTOM-ORDER-1003':'DEMO-SUBMISSION-1003'};modalRoot.innerHTML='';scenario='unlocked';markScenario();renderChannel();notify('Verified sample completion · channel unlocked.');}
function handleCustomAction(action){
 if(action==='openEmbedded'){modal(customAssets[config.custom.asset].name,embeddedAssetMarkup());return true;}
 if(action==='embeddedPaymentFailure'){document.getElementById('embeddedError').hidden=false;return true;}
 if(action==='completeEmbedded'){if(document.getElementById('embeddedAccessForm').reportValidity())customCompletion('Embedded '+customAssets[config.custom.asset].kind+' · this channel',customAssets[config.custom.asset].paid);return true;}
 if(action==='externalFunnel'){const c=config.custom,p=c.confirmation==='none'?null:catalog[c.confirmation==='context'?'course':c.confirmation];modal('External funnel · simulated page',`<p class="description">The member continues to your existing funnel. The Community does not collect payment in this path.</p><p class="hint">Destination: ${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.url)}</a>`:'sample existing Club funnel'}</p>${p?`<div class="offer-row"><div class="offer-info"><strong>${esc(p.name)}</strong><small>${p.price} · ${p.billing} · paid in the external funnel</small></div></div><p class="hint">Only a verified qualifying purchase opens this channel. The original funnel remains the purchase source.</p>`:'<p class="hint">Link-only mode: this link does not automatically grant access. Existing access automation or an admin can grant it separately.</p>'}<div class="footer"><button class="secondary" data-action="returnFromFunnel">Return without completing</button>${p?'<button class="primary" data-action="completeExternal">Simulate verified purchase & return</button>':''}</div>`);modalRoot.querySelector('.overlay').classList.add('external-handoff');return true;}
 if(action==='returnFromFunnel'){modalRoot.innerHTML='';renderChannel();notify('Returned to the channel. No access was granted.');return true;}
 if(action==='completeExternal'){customCompletion('Original external funnel',true,config.custom.confirmation==='context'?'course':config.custom.confirmation);return true;}
 return false;
}
function handleCustomChange(el){if(!el.dataset.custom)return false;draft.custom[el.dataset.custom]=el.value;if(el.dataset.custom==='kind')draft.custom.asset=Object.keys(customAssets).find(k=>customAssets[k].kind===el.value);if(['method','kind','asset','layout','confirmation'].includes(el.dataset.custom))renderSettings();return true;}

