function hasAccess(){return Object.values(grant).some(Boolean);}
function modal(title,body,wide=false,meta={}){const header=meta.back?`<button class="back-button" data-action="backSettings" aria-label="Back to channel settings"><svg class="icon" viewBox="0 0 24 24"><path d="m14 6-6 6 6 6M8 12h13"/></svg></button>`:meta.channel?`<span class="header-icon">${channelGlyph(config.icon)}${icon('lock')}</span>`:'';modalRoot.innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''} ${meta.className||''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle" tabindex="-1"><header class="modal-header">${header}<div><h2 id="dialogTitle">${esc(title)}</h2>${meta.subtitle?`<p>${esc(meta.subtitle)}</p>`:''}</div><button class="close" data-action="close" aria-label="Close dialog"><svg class="icon" viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="modal-body">${body}</div></section></div>`;requestAnimationFrame(()=>modalRoot.querySelector('.close')?.focus());}
