function feed(){const banner=grant.custom?customGrantBanner():scenario==='existing'?'<div class="status-banner"><strong>Your existing purchase was recognized.</strong>You returned to the same channel. No new order or payment was needed.</div>':scenario==='overlap'?`<div class="status-banner"><strong>${courseExpired?'Course bonus expired. The channel stays unlocked.':'Two purchases currently give access.'}</strong>${courseExpired?'The monthly Club Membership is still active.':'Course bonus: 90 days. Club Membership: active monthly subscription.'}<div class="actions">${!courseExpired?'<button class="secondary" data-action="expireBonus">Expire course bonus</button>':'<button class="secondary" data-action="endMembership">End remaining membership</button>'}</div></div>`:'';const person=(action,age)=>`<div class="person"><span class="avatar">CA</span><span>Community admin<small>${action} ${esc(config.name)}</small></span><time>${age}</time></div>`;const actions=`<div class="post-actions"><span>${icon('like')} Like</span><span>${icon('chat')} Comment</span><span>${icon('share')} Share</span></div>`;return `${banner}${config.readonly&&scenario!=='admin'?'':`<div class="composer"><span class="avatar">M</span><span>What's on your mind?</span><button class="primary" data-action="goLive">${icon('video')} Go Live</button></div>`}<section class="featured"><h2>Featured Posts ${icon('info')}</h2><article class="featured-card">${person('posted in','6mo')}<h3 class="post-title">Club meeting schedule</h3><p class="post-copy">Join our live Club calls and bring your questions. Find the next session in Events and add it to your calendar.</p><div class="schedule"><h3>Live meetings in The Club</h3><p class="post-copy">Learn together. Ask questions. Share progress.</p><span class="muted">Members-only sessions and replays</span></div><p class="hint">4 reactions</p>${actions}</article></section><div class="sort"><span>↕ &nbsp; Newest</span></div><article class="feed-post">${person('was live in','1d')}<h3 class="post-title">Club meeting · October 28</h3><p class="post-copy">Meeting replay and notes for Club members.</p><div class="replay"><span class="play">${icon('play')}</span></div><p class="hint">10 Comments</p>${actions}</article><article class="feed-post">${person('posted in','3d')}<h3 class="post-title">What would you like to cover on our next call?</h3><p class="post-copy">Share your questions and the projects you are working on. We will discuss them together at the next meeting.</p><p class="hint">5 reactions · 2 Comments</p>${actions}</article>`;}
function renderChannel(){document.getElementById('bundleLibraryRow').hidden=true;document.getElementById('channelRow').classList.add('selected');document.getElementById('channelRow').removeAttribute('role');document.getElementById('channelRow').removeAttribute('tabindex');if(scenario==='bundle'){renderBundle();return;}document.getElementById('channelRow').hidden=false;document.getElementById('channelName').textContent=config.name;document.getElementById('channelIcon').innerHTML=channelGlyph(config.icon);document.getElementById('profileAvatar').textContent=scenario==='admin'?'A':'M';if(hasAccess()||config.private===false){channelContent.innerHTML=feed();return;}const hidden=config.visibility==='hidden';document.getElementById('channelRow').hidden=hidden&&scenario!=='admin';if(hidden&&scenario!=='admin'){channelContent.innerHTML='<section class="guest"><h1 class="guest-title">All Posts</h1><p class="description">Hidden channels are not listed for members without access.</p></section>';return;}if(proposed&&(config.mode==='custom'||['embedded','external'].includes(scenario))){renderCustomAccess(scenario==='external'?'external':scenario==='embedded'?'embed':config.custom.method);return;}const free=scenario==='free'||config.mode==='free';let cta='';if(free){cta=proposed?`<p class="hint">Ask a channel manager to approve your access.</p><button class="primary" data-action="request" ${requestPending?'disabled':''}>${requestPending?'Request sent':'Request access'}</button>`:'<p class="hint">Contact a channel manager or admin to request access.</p>';}else if(proposed&&config.mode==='product'){cta=`<p class="hint">${scenario==='expired'?'Your access has ended. Choose an offer to rejoin.':'Get access with an existing Club offer.'}</p>${config.mappings.map(m=>{const p=catalog[m.offer];return `<div class="offer-row"><div class="offer-info"><strong>${esc(p.name)}</strong><small>${esc(p.price)} · ${p.billing} · ${durationText(m.duration)}</small></div><button class="primary" data-action="offer" data-offer="${m.offer}">${m.route==='sales'?'View offer':'Buy access'}</button></div>`;}).join('')}`;}else{cta='<p class="hint">Complete the payment to join the channel</p><button class="primary" data-action="checkout">Join channel</button>';}
channelContent.innerHTML=`${scenario==='existing'?`<div class="status-banner ${['missing','expired'].includes(existingCheck)?'warning':''}"><strong>${existingCheck==='expired'?'Your original course bonus has ended.':existingCheck==='missing'?'No qualifying purchase found for this sample member.':'Already purchased through another sales page?'}</strong>${existingCheck==='expired'?'Signing in does not restart the original access period. The channel stays locked; choose a renewal offer below.':existingCheck==='missing'?'The channel stays locked. Use the right account or choose an offer below.':'Sign in with the account associated with your order. Access is checked before another purchase is requested.'}<div class="actions"><button class="secondary" data-action="existingSignIn">Sign in to check access</button></div></div>`:''}${scenario==='expired'?'<div class="status-banner warning"><strong>No active access remains</strong>Posts are locked again. The expired bonus does not cancel or change any purchased product.</div>':''}<section class="guest"><h1 class="guest-title">${icon('lock')}${esc(config.name)}</h1><p class="description">${esc(config.description)}</p><div class="guest-meta">${icon('lock')} Private channel · ${config.visibility==='visible'?'Visible':'Hidden'}</div><div class="admin-line"><span class="avatar">CA</span> Created by Community admin</div>${cta}${proposed&&config.mode==='product'&&scenario!=='existing'?'<p class="hint"><button class="link-button" data-action="existingSignIn">Already purchased? Check access</button></p>':''}</section>`;}
function setScenario(s){if(!scenarios.some(x=>x[0]===s))s='locked';modalRoot.innerHTML='';scenario=s;existingCheck='pending';bundleState={purchased:false,expired:false,active:'events'};document.getElementById('channelRow').hidden=false;courseExpired=false;grant={course:false,membership:false,manual:false};if(s==='unlocked')grant.course=true;if(s==='overlap'){grant.course=true;grant.membership=true;}if(s==='admin'){grant.manual=true;returnedScenario='locked';draft=structuredClone(config);tab='about';renderChannel();renderSettings();}else if(s==='checkout'){returnedScenario='locked';selectedOffer=config.mappings[0]?.offer||'course';renderChannel();checkout();}else if(s==='order'){returnedScenario='unlocked';grant.course=true;renderChannel();showOrder();}else renderChannel();markScenario();}
function salesPage(){const m=config.mappings.find(m=>m.offer===selectedOffer),p=catalog[m.offer];modal(p.name,`<img src="assets/club-cover.webp" alt="The Club" style="width:100%;height:140px;object-fit:cover;border-radius:5px"><h3 class="post-title">Learn and grow with The Club</h3><p class="description">An example of the offer’s existing sales page: keep your own copy, images, benefits and checkout. This content belongs to the offer, rather than a new Community page builder.</p><ul class="description"><li>Live Club sessions and member discussions</li><li>Meeting replays and follow-up questions</li><li>${durationText(m.duration)}</li></ul><div class="offer-row"><strong>${p.price} · ${p.billing}</strong><button class="primary" style="margin-left:auto" data-action="continueCheckout">Continue to checkout</button></div><p class="hint">Simulated handoff. A production offer can use its existing funnel, form or checkout URL.</p>`);}
function checkout(){const m=config.mappings.find(m=>m.offer===selectedOffer)||config.mappings[0];const p=catalog[m?.offer||'course'];const linked=proposed&&config.mode==='product',oneTime=config.mode==='oneTime';modal(linked?p.name:`Join ${config.name}`,`${linked?`<p class="description">Existing ${m.route==='sales'?'offer sales page → checkout':'product checkout'}. The offer keeps its pricing, payment options, taxes, coupons and sales content.</p><div class="offer-row"><div class="offer-info"><strong>${esc(p.name)}</strong><small>${p.price} · ${p.billing}</small></div></div><p class="hint">Includes ${durationText(m.duration).toLowerCase()} in ${esc(config.name)}.</p>`:`${oneTime?`<p class="description">One-time channel purchase · ${money()}${esc(config.once)}</p>`:`<div class="radio-row"><label><input type="radio" name="billing" value="monthly" checked> Monthly · ${money()}${esc(config.monthly)}</label><label><input type="radio" name="billing" value="annual"> Annual · ${money()}${esc(config.annual)}</label></div><p class="description">Channel subscription · <strong id="checkoutTotal">${money()}${esc(config.monthly)} / month</strong></p>`}`}<div class="field"><label>Payment information</label><input disabled value="Demo — payment fields are not connected"></div><p class="hint">No real payment, account, contact or order is created.</p><p id="checkoutError" class="error" role="alert" hidden>Payment was not completed. No access was granted. Try again or close this checkout.</p><div class="footer"><button class="secondary" data-action="failPayment">Simulate failure</button><button class="primary" data-action="pay">Simulate successful ${linked||oneTime?'order':'subscription'}</button></div>`);}
function renderSettings(){let body;if(tab==='about'){body=`<div class="native-section-title"><span>Channel Details</span><button class="link-button" data-action="editChannel">Edit</button></div><div class="detail"><label>Channel Name and Icon</label><p>${channelGlyph(config.icon)} ${esc(config.name)}</p></div><div class="detail"><label>Channel Description</label><p>${esc(config.description)}</p></div><div class="detail"><label>This channel is</label><p>${config.private===false?'Public':'Private-'+(config.visibility==='visible'?'Visible':'Hidden')}</p></div><hr class="divider"><div class="detail"><label class="native-section-title">Managed by <button class="link-button" data-action="managers">Edit</button></label><p class="native-manager">Community admin${config.extraManager?' · Club member':''}</p></div><div class="detail"><label>Created by</label><p><span class="native-manager">Community admin</span> on December 22, 2025 at 04:53 PM</p></div><div class="footer"><button class="danger" data-action="delete">Delete Channel</button></div>`;}else body=tab==='pricing'?(config.private===false?'<p class="hint">Pricing is available for private channels. Public channels are open to community members.</p>':pricing()):members();modal(config.name,`<nav class="settings-tabs" aria-label="Channel settings tabs">${['about','pricing','members'].map(t=>`<button data-tab="${t}" class="${tab===t?'on':''}">${t==='members'?'Members 101':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</nav><section class="settings-content ${tab==='pricing'?'native-pricing':''}">${body}</section>`,false,{channel:true,subtitle:'View and configure channel settings',className:'native-settings'});}
function nativeSwitch(id,checked,text,extra='',large=false){return `<label class="native-switch ${large?'large':''}"><input id="${id}" type="checkbox" role="switch" ${checked?'checked':''} ${extra}><span class="switch-track"></span><span>${text}</span></label>`;}
function pricing(){const fragment=document.createElement('div');fragment.innerHTML=legacyPricing();const choices=[['free','Free','tag'],['recurring','Recurring','repeat'],['oneTime','One-time','coins'],...(proposed?[['product','Existing Product / Offer','course'],['custom','Custom access','custom']]:[])];const svg={tag:'M3 3h7l11 11-7 7L3 10zM7 7h.01',repeat:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',coins:'M12 8c4 0 7-1 7-3s-3-3-7-3-7 1-7 3 3 3 7 3zm-7-3v5c0 2 3 3 7 3m7-8v5M3 14c0-2 3-3 7-3s7 1 7 3-3 3-7 3-7-1-7-3zm0 0v5c0 2 3 3 7 3s7-1 7-3v-5',custom:'M8 3H4v18h16V3h-4M8 3v4h8V3zM8 12h8M8 16h5'};const cards=`<div class="mode-cards">${choices.map(([v,n,i])=>`<label class="mode-card ${['product','custom'].includes(v)?'proposed-mode':''}"><input type="radio" name="mode" value="${v}" ${draft.mode===v?'checked':''}><span class="mode-icon">${svg[i]?`<svg class="icon" viewBox="0 0 24 24"><path d="${svg[i]}"/></svg>`:icon(i)}</span><span>${n}</span></label>`).join('')}</div>`;if(['product','custom'].includes(draft.mode)){fragment.querySelector('.radio-row').outerHTML=cards;return fragment.innerHTML;}const currency=`<div class="field"><label for="currency">Currency</label><select id="currency" data-setting="currency"><option value="EUR" ${draft.currency==='EUR'?'selected':''}>EUR — Euro</option><option value="USD" ${draft.currency==='USD'?'selected':''}>USD — US Dollar</option></select></div>`;const row=(key,label)=>`<div class="billing-row">${draft.mode==='recurring'?nativeSwitch('enable-'+key,draft['enable-'+key]!==false,label,'data-billing-toggle="'+key+'"',true):`<span>${label}</span>`}<div class="billing-price"><span>${draft.currency==='USD'?'$':'€'}</span><input id="${key}" type="number" min="1" data-setting="${key}" value="${esc(draft[key])}" aria-label="${label} price" ${draft['enable-'+key]===false?'disabled':''}></div></div>`;return cards+(draft.mode==='free'?'<p class="mode-description">Members contact a channel manager or admin to request access.</p>':`<div class="test-mode-row"><span>Test Mode</span>${nativeSwitch('testMode',draft.testMode,'','data-setting="testMode"',true)}</div>${currency}<p class="billing-label">${draft.mode==='recurring'?'Billing options':'Price'}</p>${draft.mode==='recurring'?row('monthly','Monthly')+row('annual','Annually'):row('once','One-time')}`)+`<p id="settingsError" class="error" role="alert" hidden></p><div class="footer"><button class="secondary" data-action="cancelSettings">Cancel</button><button class="primary" data-action="savePricing">Save Changes</button></div>`;}
function legacyPricing(){return `<div class="radio-row">${[['free','Free'],['recurring','Recurring'],['oneTime','One-time'],...(proposed?[['product','Existing Product / Offer'],['custom','Custom access']]:[])].map(([v,n])=>`<label><input type="radio" name="mode" value="${v}" ${draft.mode===v?'checked':''}> ${n}</label>`).join('')}</div>${draft.mode==='product'?`<p class="hint">Any linked offer can grant access. Reuse the offer’s existing checkout or sales page.</p>${draft.mappings.map((m,i)=>`<div class="mapping"><div class="mapping-head"><strong>Offer ${i+1}</strong><button class="link-button" data-action="removeOffer" data-index="${i}" ${draft.mappings.length===1?'disabled':''}>Remove</button></div><div class="field"><label for="offer${i}">Product / offer</label><select id="offer${i}" data-map="offer" data-index="${i}">${Object.entries(catalog).map(([v,p])=>`<option value="${v}" ${m.offer===v?'selected':''}>${p.name} · ${p.price} ${p.billing}</option>`).join('')}</select></div><div class="field"><label for="duration${i}">Channel access</label><select id="duration${i}" data-map="duration" data-index="${i}">${[['30','30 days'],['90','90 days'],['custom','Custom number of days'],['subscription','While subscription is active'],['forever','Lifetime']].map(([v,n])=>`<option value="${v}" ${(m.duration===v||(v==='custom'&&!['30','90','subscription','forever'].includes(m.duration)))?'selected':''}>${n}</option>`).join('')}</select>${!['30','90','subscription','forever'].includes(m.duration)?`<label for="days${i}" style="margin-top:10px">Number of days</label><input id="days${i}" type="number" min="1" step="1" inputmode="numeric" data-days="${i}" value="${esc(m.duration)}" aria-describedby="daysHint${i}"><p id="daysHint${i}" class="hint">Positive whole days from the original successful purchase.</p>`:''}</div><div class="field"><label for="route${i}">Button destination</label><select id="route${i}" data-map="route" data-index="${i}"><option value="checkout" ${m.route==='checkout'?'selected':''}>Existing product checkout</option><option value="sales" ${m.route==='sales'?'selected':''}>Existing offer sales page → checkout</option></select></div></div>`).join('')}<button class="secondary" data-action="addOffer" ${draft.mappings.length===Object.keys(catalog).length?'disabled':''}>+ Add another offer</button><p class="hint">Access expiry affects this channel only. An active grant from another purchase, workflow or admin keeps it open.</p><p class="hint">To embed a ready-made form, quiz or survey, or show only a funnel link, choose Custom access above. Native completion in this channel can unlock it without a separate workflow.</p>`:draft.mode==='custom'?customSettings():draft.mode==='free'?'<p class="hint">Members contact a channel manager or admin to request access.</p>':`<div class="field"><label><input type="checkbox" data-setting="testMode" ${draft.testMode?'checked':''}> Test Mode</label></div><div class="field"><label for="currency">Currency</label><select id="currency" data-setting="currency"><option value="EUR">EUR — Euro</option><option value="USD" ${draft.currency==='USD'?'selected':''}>USD — US Dollar</option></select></div>${(draft.mode==='recurring'?[['monthly','Monthly'],['annual','Annually']]:[['once','One-time price']]).map(([v,n])=>`<div class="field"><label for="${v}">${n}</label><input id="${v}" type="number" min="1" data-setting="${v}" value="${esc(draft[v])}"></div>`).join('')}`}<p id="settingsError" class="error" role="alert" hidden></p><div class="footer"><button class="secondary" data-action="cancelSettings">Cancel</button><button class="primary" data-action="savePricing">Save Changes</button></div>`;}
function members(){return `<div class="member-toolbar"><div class="member-search">${icon('search')}<input id="memberSearch" placeholder="Search members" aria-label="Search members"></div>${nativeSwitch('onlyManagers',false,'Only managers')}</div><button class="link-button member-add" data-action="managers">Add Members</button><div id="memberList" class="native-members-list"><div class="admin-line"><span class="avatar">CA</span><span>Community admin</span><span class="member-role">Manager</span></div><div class="admin-line" id="sampleMember"><span class="avatar">CM</span><span>Club member</span>${config.extraManager?'<span class="member-role">Manager</span>':proposed?'<button class="link-button" style="margin-left:auto" data-action="grantManual">Grant channel access</button>':'<span class="member-role"></span>'}</div>${Array.from({length:8},(_,i)=>`<div class="admin-line sample-regular"><span class="avatar">${i+2}</span><span>Club member ${i+2}</span></div>`).join('')}</div><div class="footer"><button class="danger" data-action="delete">Delete Channel</button></div>`;}
function channelGlyph(value){return String(value).startsWith('svg:')?icon(String(value).slice(4)):esc(value);}
function pickerMarkup(){const emojis=['👍','😀','😘','😍','😆','😜','😅','😂','😱','😞','😒','😩','😭','😎','❤️','💩','😀','😃','😄','😁','😆','😅','🤣','😂','🙂','🙃','😉','😊','😇','🥰','😍','🤩','😘','😗','😚','😙','😋','😛','😜','🤪','😝','🤑','🤗','🤭','🤫','🤔','🤐','🤨','😐','😑','😶','😏','😒','🙄','😬','🤥','😌','😔','😪','🤤','😴','😷','🤒','🤕','🤢','🤮','🤧','🥵','🥶','🥴','😵','🤯','🤠','🥳','🥸','😎','🤓','🧐','📅','💬','🛡️','⭐','📚','🎓','🚀','💡','✨','🧠','📈','🎯','🏆','📣','🔔','🎉','💼','🌍','💎','🎥','📝'];return `<div class="picker-tabs"><button type="button" data-picker-tab="emojis" class="active">Emojis</button><button type="button" data-picker-tab="icons">Icons</button></div><div class="picker-content"><input id="iconSearch" class="icon-search" type="text" placeholder="Search"><div class="picker-categories">${['calendar','sun','users','spark','course','video','menu'].map(icon).join('')}</div><p class="picker-category">Recent</p><div class="icon-grid" id="emojiGrid">${emojis.map((e,i)=>`${i===16?'<span class="picker-category" style="grid-column:1/-1">Smileys & People</span>':''}<button type="button" data-emoji="${e}" aria-label="Choose ${e}">${e}</button>`).join('')}</div><div class="icon-grid" id="nativeIconGrid" hidden>${Object.keys(paths).map(k=>`<button type="button" data-symbol="${k}" aria-label="Choose ${k} icon">${icon(k)}</button>`).join('')}</div></div>`;}
function renderChannelEdit(){modal('Edit Channel',`<div class="native-edit-form"><div class="edit-field"><label for="editName">Channel name <span class="required">*</span></label><input id="editName" type="text" maxlength="60" value="${esc(config.name)}"><p class="help">Give this channel a clear, descriptive name</p></div><div class="edit-field"><label>Icon <span class="required">*</span></label><input type="hidden" id="editIcon" value="${esc(config.icon)}"><button class="icon-trigger" data-action="toggleIconPicker" aria-expanded="false"><span id="chosenIcon">${channelGlyph(config.icon)}</span><span>Select an icon or emoji</span></button><p class="help">Select an emoji or icon to help identify this channel</p><div id="iconPicker" class="icon-popover" hidden>${pickerMarkup()}</div></div><div class="edit-field"><label for="editDescription">Description</label><div class="description-input"><textarea id="editDescription" maxlength="500">${esc(config.description)}</textarea><span class="word-count" id="descriptionCount">${config.description.length} / 500</span></div><p class="help">Help others understand what discussions belong here</p></div><div class="edit-field"><label>Private channel</label>${nativeSwitch('editPrivate',config.private!==false,config.private===false?'All community members can join':'Only invited members can join')}<p class="help">When a channel is private, only invited members can join and view messages</p><div class="visibility-cards" ${config.private===false?'hidden':''}><label class="visibility-card"><input type="radio" name="editVisibility" value="visible" ${config.visibility==='visible'?'checked':''}><span class="card-title">Visible</span><span class="card-copy">This channel appears in the list for non-members to spark interest before they join to view posts and resources.</span></label><label class="visibility-card"><input type="radio" name="editVisibility" value="hidden" ${config.visibility==='hidden'?'checked':''}><span class="card-title">Hidden</span><span class="card-copy">This channel stays off the list for non-members, so it remains truly private.</span></label></div></div><div class="edit-field read-only"><label>Read Only Channel</label>${nativeSwitch('editReadonly',config.readonly,'Only admins can post')}<p class="help">Members can view important informations and updates, but only admins/owners of the channel can post here.</p></div></div><p id="editError" class="error" hidden>Enter a channel name.</p><div class="footer"><button class="primary" data-action="saveChannel">Save Changes</button></div>`,false,{back:true,subtitle:'Update channel name, description, and settings',className:'native-edit'});}
function persist(){try{sessionStorage.setItem(`comm005-${proposed}`,JSON.stringify(config));}catch{}renderChannel();}
function showOrder(){if(receipt?.kind==='submission'){showSubmissionActivity();return;}const r=receipt||{offer:'Club Course · Full access',total:'€149',source:'Community channel',channel:config.name,duration:'90 days',id:'DEMO-1001'};modal('Order details',`<p class="hint">Illustrative fields in the existing order/contact history. No extra member-facing access screen.</p><table class="summary-table"><tbody>${[['Order',r.id],['Product / offer',r.offer],['Total',r.total],['Purchase source',r.source],['Community / channel',r.channel],['Access granted',r.duration],['Return destination','The same channel'],['Existing tracking','Preserve funnel/page, UTM, campaign and payment identifiers']].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table><p class="hint">When purchased elsewhere, retain that original source; record the channel as an access benefit. Do not overwrite the original purchase attribution.</p><div class="footer"><button class="primary" data-action="returnFeed">Back to channel</button></div>`,true);}
function existingSignIn(){modal('Check your existing access',`<p class="description">Sample sign-in and purchase lookup. The real platform authenticates the member and checks eligible orders on the server, preserving the channel return URL.</p><div class="offer-row"><div class="offer-info"><strong>Existing course customer</strong><small>Already paid through the original course funnel · active channel benefit</small></div></div><div class="footer"><button class="secondary" data-action="unmatchedBuyer">No eligible purchase</button><button class="secondary" data-action="expiredBuyer">Expired course bonus</button><button class="primary" data-action="recognizeBuyer">Sign in as course customer</button></div><p class="hint">No credentials are requested. An expired bonus must not restart just because the member signs in.</p>`);}
function bundleDays(){const d=config.mappings.find(m=>m.offer==='course')?.duration;return d&&!['forever','subscription'].includes(d)?d:'90';}
function bundleCheckout(){modal('Club Course · Full access',`<p class="description">One existing product, one checkout, one order. Each channel receives its own access grant.</p><table class="summary-table"><tr><th>Channel</th><th>Included access</th></tr><tr><td>${esc(config.name)}</td><td>${durationText(bundleDays())}</td></tr><tr><td>Course Library</td><td>Lifetime</td></tr></table><p class="description">Total: <strong>€149 · one-time</strong></p><p class="hint">Sample only. No payment or real order is created.</p><div class="footer"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-action="confirmBundle">Simulate one successful order</button></div>`);}
function renderBundle(){
 document.getElementById('profileAvatar').textContent='M';
 const library=bundleState.active==='library',active=bundleState.purchased&&(library||!bundleState.expired);
 const row=document.getElementById('channelRow'),lib=document.getElementById('bundleLibraryRow');row.hidden=false;row.classList.toggle('selected',!library);row.setAttribute('role','button');row.setAttribute('tabindex','0');lib.hidden=false;lib.classList.toggle('selected',library);
 document.getElementById('channelName').textContent=config.name;document.getElementById('channelIcon').innerHTML=channelGlyph(config.icon);
 const summary=`<section class="guest bundle-summary"><h1 class="guest-title">One purchase, two channel benefits</h1><p class="hint">The same Club Course offer is linked independently in each channel’s Pricing. Meetings: ${esc(bundleDays())} days. Course Library: lifetime. No additional product or checkout is needed.</p><table class="summary-table"><thead><tr><th>Channel</th><th>Access from the same order</th><th></th></tr></thead><tbody><tr><td>${esc(config.name)}</td><td>${bundleState.purchased?(bundleState.expired?'Expired':'Active · '+esc(bundleDays())+' days'):'Locked · '+esc(bundleDays())+' days included'}</td><td><button class="link-button" data-action="bundleEvents">Open</button></td></tr><tr><td>Course Library</td><td>${bundleState.purchased?'Active · lifetime':'Locked · lifetime included'}</td><td><button class="link-button" data-action="bundleLibrary">Open</button></td></tr></tbody></table><div class="actions">${!bundleState.purchased?'<button class="primary" data-action="buyBundle">Buy Club Course · €149 once</button>':!bundleState.expired?`<button class="secondary" data-action="expireBundle">Advance ${esc(bundleDays())} days</button>`:'<p class="hint">The meeting bonus has ended. Your purchased course and Course Library remain available.</p>'}</div></section>`;
 let content;
 if(!active)content=`<section class="guest"><h2 class="guest-title">${icon('lock')}${esc(library?'Course Library':config.name)}</h2><p class="description">${bundleState.purchased?'The meeting bonus has expired. Open Course Library to see the lifetime access retained from the same purchase.':'Posts stay locked until the one qualifying order succeeds.'}</p></section>`;
 else if(library)content=`<section class="feed-post"><h2 class="guest-title">Course Library</h2><div class="status-banner"><strong>Lifetime access · same Club Course purchase</strong>The end of your meeting bonus does not remove your library access.</div><article><h3 class="post-title">Start here: your course resources</h3><p class="post-copy">Lessons, worksheets and reference materials included with your course.</p></article><hr class="divider"><article><h3 class="post-title">Course updates and member questions</h3><p class="post-copy">Your learning resources remain available after the live-meeting bonus ends.</p></article></section>`;
 else content=feed();
 channelContent.innerHTML=summary+content;
}
document.addEventListener('click',e=>{const pt=e.target.closest('[data-picker-tab]');if(pt){document.getElementById('emojiGrid').hidden=pt.dataset.pickerTab!=='emojis';document.getElementById('nativeIconGrid').hidden=pt.dataset.pickerTab!=='icons';document.querySelectorAll('[data-picker-tab]').forEach(x=>x.classList.toggle('active',x===pt));return;}const sym=e.target.closest('[data-symbol]');if(sym){document.getElementById('editIcon').value='svg:'+sym.dataset.symbol;document.getElementById('chosenIcon').innerHTML=icon(sym.dataset.symbol);document.getElementById('iconPicker').hidden=true;return;}const emoji=e.target.closest('[data-emoji]');if(emoji){document.getElementById('editIcon').value=emoji.dataset.emoji;document.getElementById('chosenIcon').textContent=emoji.dataset.emoji;document.getElementById('iconPicker').hidden=true;return;}const s=e.target.closest('[data-scenario]');if(s){setScenario(s.dataset.scenario);return;}const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;renderSettings();return;}const b=e.target.closest('[data-action]');if(!b){if(scenario==='bundle'&&e.target.closest('#channelRow')){bundleState.active='events';renderBundle();}return;}const a=b.dataset.action;
if(a==='reset'){config=defaults();persist();receipt=null;requestPending=false;setScenario('locked');notify('Demo reset. All sample settings restored.');}
else if(a==='existingSignIn'){if(scenario!=='existing')setScenario('existing');existingSignIn();}
else if(a==='recognizeBuyer'){existingCheck='recognized';grant.course=true;receipt={offer:'Club Course · Full access',total:'€149',source:'Original course sales funnel',channel:config.name,duration:durationText(config.mappings.find(m=>m.offer==='course')?.duration||'90'),id:'DEMO-EXISTING-1000'};modalRoot.innerHTML='';renderChannel();notify('Existing eligibility verified in this sample. No new purchase.');}
else if(a==='expiredBuyer'){existingCheck='expired';modalRoot.innerHTML='';renderChannel();}
else if(a==='unmatchedBuyer'){existingCheck='missing';modalRoot.innerHTML='';renderChannel();}
else if(a==='buyBundle')bundleCheckout();
else if(a==='confirmBundle'){bundleState.purchased=true;modalRoot.innerHTML='';receipt={offer:'Club Course · Full access',total:'€149',source:'Community channel',channel:config.name+' + Course Library',duration:durationText(bundleDays())+'; Course Library: lifetime',id:'DEMO-BUNDLE-1002'};renderBundle();notify('One sample order unlocked both channels.');}
else if(a==='bundleLibrary'){bundleState.active='library';renderBundle();}
else if(a==='bundleEvents'){bundleState.active='events';renderBundle();}
else if(a==='expireBundle'){bundleState.expired=true;renderBundle();notify('Meeting access ended. Course Library stays available.');}
else if(a==='menu')document.querySelector('.sidebar').classList.toggle('mobile-open');
else if(a==='close')dismiss();
else if(a==='settings')setScenario('admin');
else if(a==='offer'){selectedOffer=b.dataset.offer;returnedScenario=scenario;scenario='checkout';markScenario();const m=config.mappings.find(m=>m.offer===selectedOffer);if(m?.route==='sales')salesPage();else checkout();}
else if(a==='continueCheckout')checkout();
else if(a==='checkout'){returnedScenario=scenario;scenario='checkout';markScenario();checkout();}
else if(a==='failPayment')document.getElementById('checkoutError').hidden=false;
else if(a==='pay'){const m=config.mappings.find(m=>m.offer===selectedOffer)||config.mappings[0],p=catalog[m.offer];receipt={offer:proposed&&config.mode==='product'?p.name:config.name,total:proposed&&config.mode==='product'?p.price:config.mode==='oneTime'?`${money()}${config.once}`:document.querySelector('input[name=billing]:checked')?.value==='annual'?`${money()}${config.annual}`:`${money()}${config.monthly}`,source:'Community channel',channel:config.name,duration:durationText(m.duration),id:'DEMO-1001'};modalRoot.innerHTML='';scenario='unlocked';grant.course=true;renderChannel();markScenario();notify('Sample order succeeded. Returned to the same channel.');}
else if(a==='expireBonus'){grant.course=false;courseExpired=true;renderChannel();notify('Course bonus expired. Membership still grants access.');}
else if(a==='endMembership'){grant.membership=false;if(!hasAccess()){scenario='expired';markScenario();}renderChannel();notify('The last active grant ended. Posts are locked.');}
else if(a==='returnFeed'){modalRoot.innerHTML='';scenario='unlocked';grant.course=true;renderChannel();markScenario();}
else if(a==='addOffer'){const offer=Object.keys(catalog).find(o=>!draft.mappings.some(m=>m.offer===o));if(offer)draft.mappings.push({offer,duration:catalog[offer].duration,route:catalog[offer].route});renderSettings();}
else if(a==='removeOffer'){draft.mappings.splice(Number(b.dataset.index),1);renderSettings();}
else if(a==='cancelSettings'){draft=structuredClone(config);dismiss();}
else if(a==='savePricing'){const err=document.getElementById('settingsError');let error=draft.mode==='custom'?validateCustomAccess():'';if(draft.mode==='product'&&draft.mappings.some(m=>!['subscription','forever'].includes(m.duration)&&(!Number.isSafeInteger(Number(m.duration))||Number(m.duration)<1)))error='Enter a positive whole number of days for each custom access period.';if(draft.mode==='product'&&new Set(draft.mappings.map(m=>m.offer)).size!==draft.mappings.length)error='Select a different product or offer in each row.';if(draft.mode==='product'&&draft.mappings.some(m=>m.duration==='subscription'&&catalog[m.offer].billing!=='monthly'))error='“While subscription is active” requires a recurring offer. Choose a fixed duration or Lifetime for a one-time purchase.';if(draft.mode==='recurring'&&(!(+draft.monthly>0)||!(+draft.annual>0)))error='Enter a positive monthly and annual price.';if(draft.mode==='oneTime'&&!(+draft.once>0))error='Enter a positive one-time price.';if(error){err.textContent=error;err.hidden=false;return;}config=structuredClone(draft);grant={course:false,membership:false,manual:false};persist();modalRoot.innerHTML='';scenario='locked';markScenario();renderChannel();notify('Sample settings saved. The locked channel now uses these offers.');}
else if(a==='editChannel')renderChannelEdit();
else if(a==='toggleIconPicker'){const p=document.getElementById('iconPicker');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));}
else if(a==='saveChannel'){const name=document.getElementById('editName').value.trim();if(!name){document.getElementById('editError').hidden=false;return;}config.name=name;config.private=document.getElementById('editPrivate').checked;config.icon=document.getElementById('editIcon').value;config.description=document.getElementById('editDescription').value;config.visibility=document.querySelector('input[name=editVisibility]:checked').value;config.readonly=document.getElementById('editReadonly').checked;persist();draft=structuredClone(config);tab='about';renderSettings();notify('Channel details updated in this demo only.');}
else if(a==='backSettings'){tab='about';renderSettings();}
else if(a==='managers')modal('Channel Managers',`<div class="field"><label for="managerSearch">Search members</label><input id="managerSearch" placeholder="Search members..."></div><div class="admin-line"><span class="avatar">CA</span> Community admin <span style="margin-left:auto">Manager</span></div><label class="hint"><input type="checkbox" id="addManager"> Club member</label><div class="footer"><button class="secondary" data-action="backSettings">Cancel</button><button class="primary" data-action="saveManagers">Add Managers</button></div>`);
else if(a==='saveManagers'){if(document.getElementById('addManager').checked){config.extraManager=true;persist();notify('Club member added as a manager in this sample.');}tab='members';renderSettings();}
else if(a==='grantManual'){grant.manual=true;modalRoot.innerHTML='';scenario='unlocked';markScenario();renderChannel();notify('Sample manual grant added. No purchase was created.');}
else if(a==='request'){requestPending=true;renderChannel();notify('Sample request sent to channel managers. Approval is still required.');}
else if(a==='delete')modal('Delete channel?',`<p class="description">This control is shown for fidelity to Channel Settings. Channel deletion is intentionally disabled in this demo.</p><div class="footer"><button class="primary" data-action="backSettings">Keep channel</button></div>`);
else if(handleCustomAction(a))return;
else notify(({invite:'Invitations are outside this channel-access demo.',badges:'Badge setup is outside this channel-access demo.',goLive:'Live broadcasting is outside this channel-access demo.'})[a]||'Demo only.');});
document.addEventListener('change',e=>{const el=e.target;if(handleCustomChange(el))return;if(el.dataset.billingToggle){draft['enable-'+el.dataset.billingToggle]=el.checked;renderSettings();return;}if(el.id==='editPrivate'){document.querySelector('.visibility-cards').hidden=!el.checked;el.closest('label').querySelector('span:last-child').textContent=el.checked?'Only invited members can join':'All community members can join';return;}if(el.name==='mode'){draft.mode=el.value;renderSettings();}else if(el.dataset.map){draft.mappings[Number(el.dataset.index)][el.dataset.map]=el.value==='custom'?'45':el.value;if(el.dataset.map==='offer'){const m=draft.mappings[Number(el.dataset.index)];m.duration=catalog[m.offer].duration;}renderSettings();}else if(el.dataset.setting)draft[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value;else if(el.name==='billing')document.getElementById('checkoutTotal').textContent=el.value==='annual'?`${money()}${config.annual} / year`:`${money()}${config.monthly} / month`;else if(el.id==='onlyManagers'){document.getElementById('sampleMember').hidden=el.checked&&!config.extraManager;document.querySelectorAll('.sample-regular').forEach(r=>r.hidden=el.checked);}});
document.addEventListener('input',e=>{if(e.target.id==='editDescription')document.getElementById('descriptionCount').textContent=e.target.value.length+' / 500';if(e.target.id==='iconSearch'){const q=e.target.value.trim();const names={'📅':'calendar meeting date','⭐':'star favorite','📚':'books library','💬':'chat discussion','🛡️':'shield private','🎓':'course education','🚀':'rocket','❤️':'heart','😀':'smile happy'};document.querySelectorAll('[data-emoji]').forEach(x=>x.hidden=!!q&&!(x.dataset.emoji+' '+(names[x.dataset.emoji]||'')).toLowerCase().includes(q.toLowerCase()));document.querySelectorAll('[data-symbol]').forEach(x=>x.hidden=!!q&&!x.dataset.symbol.includes(q.toLowerCase()));}if(e.target.dataset.custom){handleCustomChange(e.target);return;}if(e.target.hasAttribute('data-custom-description')){draft.description=e.target.value;return;}if(e.target.dataset.days!==undefined)draft.mappings[Number(e.target.dataset.days)].duration=e.target.value;if(e.target.dataset.setting)draft[e.target.dataset.setting]=e.target.value;if(e.target.id==='managerSearch'){const q=e.target.value.toLowerCase();document.getElementById('addManager').parentElement.hidden=!('club member'.includes(q));}if(e.target.id==='memberSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#memberList .admin-line').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('keydown',e=>{if(scenario==='bundle'&&e.target.id==='channelRow'&&['Enter',' '].includes(e.key)){e.preventDefault();bundleState.active='events';renderBundle();return;}if(!modalRoot.firstChild)return;if(e.key==='Escape'){dismiss();return;}if(e.key==='Tab'){const all=[...modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(n=>n.getClientRects().length);if(!all.length)return;const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
modalRoot.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))dismiss();});
setScenario(new URLSearchParams(location.search).get('scenario')||'locked');
